Translate("frFR", "ironforge", {
	title = "Ironforge",
	aliases = { "cité d'Ironforge" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ironforge est la capitale du {link:kingdom-of-ironforge}royaume d'Ironforge{/link} et la plus ancienne cité des {link:dwarves}nains{/link}. Elle est taillée au cœur d'une montagne de {link:dun-morogh}Dun Morogh{/link}, et même la {link:horde}Horde{/link}, au sommet de sa puissance, ne put la prendre. En son centre, les feux de la {link:the-great-forge}Great Forge{/link} brûlent jour et nuit, et les rivières de métal en fusion qui les nourrissent éclairent toute la cité de rouge et d'or. Autour de la forge s'étendent les salles du commerce, du savoir, de la magie et de la guerre, et sous le trône se trouvent des salles plus anciennes encore.]=],
		},
		{
			title = "Origines",
			text = [=[Les nains tiennent Ironforge pour leur premier foyer, et croient que leur peuple fut façonné dans la pierre de ces montagnes en des âges reculés. Aucune chronique ne dit en quelle année ses premières salles furent creusées. Pendant de longs âges, tous les nains furent gouvernés depuis Ironforge par un seul haut roi. À sa mort, les clans Bronzebeard, Wildhammer et Sombrefer se disputèrent son trône. Les Bronzebeard gardèrent la cité, et quand les {link:dark-iron-dwarves}Sombrefer{/link} revinrent pour la prendre, ils furent brisés devant ses portes.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} règne depuis {link:high-seat}le High Seat{/link}, avec à ses côtés le Sénat d'Ironforge, qui n'est pas toujours d'accord avec lui. Une grande partie de son armée est loin, au service de l'{link:alliance}Alliance{/link}. Son frère {link:muradin-bronzebeard}Muradin Bronzebeard{/link} a disparu dans le Nord, et son frère {link:brann-bronzebeard}Brann Bronzebeard{/link} parcourt le monde. Sa fille Moira n'est plus là, et il croit que l'empereur sombrefer l'a enlevée. Les gnomes de {link:gnomeregan}Gnomeregan{/link} vivent à {link:tinker-town}Tinker Town{/link} depuis la chute de leur cité, et leurs bricoleurs emplissent les salles de bruit. Désormais, les anciennes voies scellées sous le High Seat ont été ouvertes. Quelque chose trouble les tombeaux des thanes, et l'on a surpris les {link:dark-iron-dwarves}Sombrefer{/link} à creuser dans leur direction.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les nains Bronzebeard.{/b} Forgerons, marchands, soldats, prêtres et érudits peuplent les quartiers de la cité.
• {b}Les {link:gnomeregan-exiles}Exilés de Gnomeregan{/link}.{/b} Le grand artisan {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} guide son peuple depuis {link:tinker-town}Tinker Town{/link}.
• {b}La Ligue des explorateurs.{/b} Depuis le {link:hall-of-explorers}Hall of Explorers{/link}, la {link:explorers-league}Ligue des explorateurs{/link} envoie ses membres dans des ruines du monde entier.
• {b}Les voyageurs de l'{link:alliance}Alliance{/link}.{/b} Des humains vont et viennent par le tram {link:gnomes}gnome{/link} depuis {link:stormwind-city}Stormwind{/link}.
• {b}Des voleurs dans l'ombre.{/b} Dans la Forlorn Cavern, une société appelée le Hidden Circle complote pour s'emparer d'une part des richesses du roi.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les Trois Marteaux.{/b} Les Bronzebeard défendirent Ironforge contre leurs frères. Une tablette de traité gardée dans les caveaux royaux consigne la paix qui suivit : signée par les Bronzebeard et les Wildhammer, et jamais par les {link:dark-iron-dwarves}Sombrefer{/link}.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} La {link:horde}Horde{/link} submergea Khaz Modan, mais Ironforge tint bon. Les nains rejoignirent l'{link:alliance}Alliance de Lordaeron{/link} et combattirent jusqu'à ce que la Horde fût brisée.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} {link:muradin-bronzebeard}Muradin{/link} partit pour le Norfendre et ne revint pas. Les nains le comptent parmi les morts.
• {b}La chute de {link:gnomeregan}Gnomeregan{/link}.{/b} Quand les gnomes perdirent leur cité, {link:magni-bronzebeard}Magni{/link} leur ouvrit Ironforge.
• {b}Aujourd'hui.{/b} Les salles sous {link:high-seat}le High Seat{/link} sont de nouveau ouvertes, et le royaume apprend que son plus vieil ennemi creuse en direction de ses plus anciens morts.]=],
		},
		{
			title = "Légendes de la montagne",
			text = [=[• Un maçon d'Ironforge tailla un mémorial pour Sully Balloo, un soldat mort loin de chez lui, dans une belle pierre rapportée des ruines de {link:lordaeron}Lordaeron{/link}. Le roi le paya lui-même.
• Les montagnards qui meurent dans les neiges de {link:dun-morogh}Dun Morogh{/link} reviennent chez eux sous forme de fusils, leur nom gravé dans la crosse.]=],
		},
	},
})

Translate("frFR", "the-great-forge", {
	title = "The Great Forge",
	aliases = { "Great Forge" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Great Forge occupe la salle centrale d'{link:ironforge}Ironforge{/link}. Le métal en fusion se déverse des hauteurs dans de grands bassins, et autour d'eux, les forgerons de la cité travaillent sur des enclumes qui ne refroidissent jamais. La chaleur et la lumière de la forge atteignent chaque quartier, et son martèlement est le son que les nains appellent leur foyer. Marchands, maîtres de métier et messagers se pressent autour de son anneau, et les griffons de la cité vont et viennent depuis la terrasse voisine. Aucun autre lieu de la cité n'est aussi animé, et aucun n'est aussi aimé.]=],
		},
	},
})

Translate("frFR", "the-commons", {
	title = "The Commons",
	sections = {
		{
			title = "Résumé",
			text = [=[The Commons est le quartier du commerce d'{link:ironforge}Ironforge{/link}. Là se dressent le Vault of Ironforge, où la richesse de la cité et celle de ses visiteurs sont gardées sous bonne escorte, le grand hall des enchères et l'auberge de l'aubergiste Firebrew. Des marchands de tous les peuples de l'{link:alliance}Alliance{/link} viennent ici, et le quartier résonne de marchandages de la première à la dernière heure. Les voyageurs longtemps restés sur la route viennent à l'auberge chercher un foyer chaud et une bière forte avant de repartir.]=],
		},
	},
})

Translate("frFR", "hall-of-explorers", {
	title = "Hall of Explorers",
	aliases = { "Assemblée des explorateurs" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Hall of Explorers est le siège de la {link:explorers-league}Ligue des explorateurs{/link}. Ses galeries abritent des reliques rapportées de ruines du monde entier, sa bibliothèque conserve les livres et les cartes de la Ligue, et ses érudits débattent des véritables origines du peuple {link:dwarves}nain{/link}. Le grand explorateur {link:high-explorer-magellas}Magellas{/link} y préside. Le conseiller {link:advisor-belgrum}Belgrum{/link}, l'historien {link:historian-karnik}Karnik{/link} et le prospecteur {link:stormpike-guard}Stormpike{/link} y mènent leurs affaires, et les nouvelles des sites de fouilles des {link:badlands}Terres ingrates{/link} et du {link:loch-modan}Loch Modan{/link} arrivent ici en premier.]=],
		},
	},
})

Translate("frFR", "tinker-town", {
	title = "Tinker Town",
	sections = {
		{
			title = "Résumé",
			text = [=[Tinker Town est le quartier que le {link:magni-bronzebeard}roi Magni{/link} donna aux gnomes après la chute de {link:gnomeregan}Gnomeregan{/link}. Il cliquette d'engrenages et siffle de vapeur, et ses ateliers sont encombrés d'appareils à moitié construits. Le {link:gelbin-mekkatorque}grand artisan Mekkatorque{/link} y tient sa cour en exil. Depuis Tinker Town, le Tram des profondeurs file loin sous la terre jusqu'à {link:stormwind-city}Stormwind{/link}, et les bricoleurs de Gnomeregan renvoient des volontaires dans leur cité perdue pour sauver ce qu'ils peuvent.]=],
		},
	},
})

Translate("frFR", "the-mystic-ward", {
	title = "The Mystic Ward",
	aliases = { "Mystic Ward" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Mystic Ward est le quartier de la cité consacré à la foi et à la magie. Des prêtres de la {link:holy-light}Lumière sacrée{/link} servent dans le Hall of Mysteries, et des mages étudient dans les salles alentour. C'est un lieu plus paisible que le reste d'{link:ironforge}Ironforge{/link}, loin du grondement de la forge, et ceux qui recherchent les arts supérieurs y trouvent leurs maîtres.]=],
		},
	},
})

Translate("frFR", "the-military-ward", {
	title = "The Military Ward",
	aliases = { "Military Ward" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Military Ward est la forteresse dans la forteresse. Son Hall of Arms forme les guerriers d'{link:ironforge}Ironforge{/link} sous l'autorité de Muren {link:stormpike-guard}Stormpike{/link}, qui enseigne qu'un guerrier ne tourne jamais le dos à un ennemi. Les soldats du roi s'y entraînent avant de marcher vers les fronts de l'{link:alliance}Alliance{/link}. C'est un lieu rude, et les nains qui y servent en sont fiers.]=],
		},
	},
})

Translate("frFR", "high-seat", {
	title = "High Seat",
	aliases = { "le High Seat" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le High Seat est la salle du trône d'{link:ironforge}Ironforge{/link}, surélevée au-dessus des salles occidentales de la cité. Le {link:magni-bronzebeard}roi Magni Bronzebeard{/link} y tient sa cour, protégé par la Garde royale de fer. Les sénateurs d'Ironforge vont et viennent pour les affaires du royaume, et l'historienne royale garde la mémoire du royaume près du trône. Une porte sur le côté de la salle, longtemps scellée, est désormais ouverte. Au-delà, un chemin descend vers {link:old-ironforge}Old Ironforge{/link}.]=],
		},
	},
})

Translate("frFR", "old-ironforge", {
	title = "Old Ironforge",
	sections = {
		{
			title = "Résumé",
			text = [=[Old Ironforge s'étend sous {link:high-seat}le High Seat{/link} : c'est la partie la plus ancienne de la cité. Pendant des générations, ses portes restèrent fermées, et peu de nains vivants y avaient marché. Désormais, la voie est ouverte. Un long chemin serpente à travers d'anciennes salles jusqu'aux cavernes en contrebas, où le {link:hall-of-thanes}Hall of Thanes{/link} abrite les tombeaux des grands nains du passé. Les gardiens de ces tombeaux ont entendu des bruits étranges venir des caveaux, et les morts qui y reposent ont commencé à s'agiter.]=],
		},
	},
})

Translate("frFR", "magni-bronzebeard", {
	title = "Magni Bronzebeard",
	subtitle = "Roi d'Ironforge",
	found = "Le High Seat, Ironforge",
	hint = "Sollicitez une audience auprès du roi, dans le High Seat.",
	allegiance = "Royaume d'Ironforge · Alliance",
	aliases = { "Magni", "roi Magni", "roi Magni Bronzebeard" },
	sections = {
		{
			title = "Résumé",
			text = [=[Magni Bronzebeard est roi d'{link:ironforge}Ironforge{/link} et seigneur des nains Bronzebeard. Il est l'aîné de trois frères, et la couronne la plus lourde de Khaz Modan repose sur sa tête. Depuis {link:high-seat}le High Seat{/link}, il gouverne un peuple fier et obstiné, négocie avec un Sénat qui ne partage pas toujours ses vues, et reste fidèle à une {link:alliance}Alliance{/link} qui lui a coûté cher.]=],
		},
		{
			title = "Importance",
			text = [=[Magni est l'un des piliers de l'{link:alliance}Alliance{/link}. Quand la {link:horde}Horde{/link} submergea Khaz Modan pendant la {link:second-war}Deuxième Guerre{/link}, son peuple n'oublia pas qui s'était tenu à ses côtés, et {link:ironforge}Ironforge{/link} a tenu parole envers l'humanité depuis lors. Quand les gnomes perdirent leur cité, il les accueillit. Quand l'Alliance appelle, ses soldats partent. C'est le fardeau de Magni que chacun de ces choix ait été payé par son propre peuple.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige le royaume d'{link:ironforge}Ironforge{/link} et y occupe son siège au sein de l'{link:alliance}Alliance{/link}.
• Il envoie son armée à l'étranger combattre aux côtés de l'Alliance, bien que cela laisse ses propres terres peu gardées.
• Il offrit un foyer dans sa cité aux {link:gnomeregan-exiles}exilés de Gnomeregan{/link}.
• Il pleure son frère {link:muradin-bronzebeard}Muradin{/link}, perdu en Norfendre. Son frère {link:brann-bronzebeard}Brann{/link} est au loin, pour les affaires de la Ligue.
• Il cherche sa fille Moira, disparue dans {link:burning-steppes}les Steppes{/link} ardentes, et il en tient l'empereur sombrefer pour responsable.]=],
		},
	},
	chapters = {
		{
			title = "L'hommage d'un roi",
			hint = [=[Accomplissez le souhait du roi pour la veuve d'un soldat tombé.]=],
			text = [=[Quand la veuve de Sully Balloo lui écrivit, Magni ne prétendit pas que la mort de son mari eût été autre chose qu'une perte. Il dit que chaque {link:dwarves}nain{/link} qui tombe pour l'{link:alliance}Alliance{/link} pèse sur son âme. Il ne pouvait pas ramener Sully, alors il fit tailler par le grand maçon un mémorial en granit de {link:lordaeron}Lordaeron{/link}, dans l'espoir que ceux qui viendraient après se souviennent pour qui de tels soldats étaient morts.]=],
		},
		{
			title = "Le traité d'entente",
			hint = "Récupérez un ancien traité dans les caveaux sous la cité.",
			text = [=[Du Reliquaire des rois, sous {link:ironforge}Ironforge{/link}, vint une tablette de pierre. Magni la reconnut aussitôt. C'était la paix conclue après la guerre des trois clans, au temps de son ancêtre Madoran, le premier Bronzebeard à régner sur Ironforge. Les Bronzebeard l'avaient signée, et les Wildhammer l'avaient signée. Les {link:dark-iron-dwarves}Sombrefer{/link}, non.]=],
		},
		{
			title = "Sous nos pieds",
			hint = "Mettez fin à l'incursion sombrefer sous Ironforge.",
			text = [=[La nouvelle qu'une force sombrefer avait été découverte sous la cité prit le roi par surprise. Il se réjouit d'apprendre que son commandant était mort, et ordonna aussitôt que les brèches soient scellées et les salles inférieures renforcées. Il envoya aussi ses chaleureuses salutations à un vieil ami wildhammer, le voyant de la terre {link:earthseer-farsen}Farsen{/link}, avec l'exigence que Farsen vienne lui rendre une vraie visite.]=],
		},
		{
			title = "La princesse perdue",
			hint = "Apprenez ce qu'il est advenu de la fille du roi.",
			text = [=[Magni pleura en parlant de Moira. Il avait envoyé ses hommes fouiller {link:burning-steppes}les Steppes{/link} ardentes, et le seul indice qu'ils trouvèrent menait dans les profondeurs de {link:blackrock-mountain}Blackrock{/link}. Il la croyait captive de l'empereur sombrefer, Dagran {link:ruins-of-thaurissan}Thaurissan{/link}, liée par ses sortilèges, et il voulait la mort de l'empereur. Quand la vérité lui revint, elle était pire que ce qu'il avait craint. Moira portait l'enfant de Thaurissan, et elle fit savoir que l'héritier d'{link:ironforge}Ironforge{/link} serait un {link:dark-iron-dwarves}Sombrefer{/link}. Magni put seulement dire que, même dans la mort, Thaurissan avait gagné.]=],
		},
	},
	mentions = {
		{ text = "L'hommage d'un roi" },
		{ text = "La négociation de la paix" },
		{ text = "Kharan Mighthammer" },
		{ text = "Le porteur de mauvaises nouvelles" },
		{ text = "Le destin du royaume" },
	},
	bonds = {
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "son frère, perdu en Norfendre" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "son plus jeune frère" },
		{ id = "gelbin-mekkatorque", name = "Gelbin Mekkatorque", note = "son allié et son hôte" },
		{ id = "earthseer-farsen", name = "Voyant de la terre Farsen", note = "un vieil ami wildhammer" },
		{ id = "royal-historian-archesonus", name = "Historienne royale Archesonus", note = "garde la mémoire de son royaume" },
		{ id = "senator-barin-redstone", name = "Sénateur Barin Redstone", note = "un sénateur de sa cour" },
	},
})

Translate("frFR", "muradin-bronzebeard", {
	title = "Muradin Bronzebeard",
	subtitle = "Frère du roi",
	found = "Perdu en Norfendre",
	allegiance = "Royaume d'Ironforge",
	aliases = { "Muradin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Muradin Bronzebeard est le frère du {link:magni-bronzebeard}roi Magni{/link}. Il était l'un des plus puissants guerriers d'{link:ironforge}Ironforge{/link}, un {link:dwarves}nain{/link} d'une grande force, au franc-parler et au cœur chaleureux. Pendant la {link:third-war}Troisième Guerre{/link}, il partit pour le continent glacé du Norfendre, et il ne revint pas. Ironforge le compte parmi ses morts.]=],
		},
		{
			title = "Importance",
			text = [=[Muradin était lié à la maison de {link:lordaeron}Lordaeron{/link} par plus qu'une alliance. Il avait été le maître d'armes du jeune prince {link:arthas-menethil}Arthas Menethil{/link}, et les deux étaient amis. Ce lien fit de Muradin le témoin des premiers pas du prince vers la ruine. Il lui coûta aussi la vie, du moins le croit-on à {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il servit l'{link:alliance}Alliance{/link} et était connu dans les cours des royaumes humains.
• Il enseigna au prince de {link:lordaeron}Lordaeron{/link} l'art de l'épée et du marteau.
• Il mena une expédition de nains en Norfendre à la recherche d'une lame runique légendaire appelée Deuillegivre.
• Il combattit aux côtés d'{link:arthas-menethil}Arthas{/link} contre les morts-vivants dans les étendues glacées.]=],
		},
		{
			title = "Le voyage vers le Nord",
			text = [=[La compagnie de Muradin cherchait Deuillegivre en Norfendre depuis longtemps quand elle rencontra {link:arthas-menethil}Arthas{/link}, qui avait suivi un seigneur de l'effroi de l'autre côté de la mer. Les nains et le prince unirent leurs forces contre les morts-vivants. Muradin devint inquiet en observant son ancien élève. Arthas avait brûlé ses propres navires pour que ses hommes ne puissent pas rentrer chez eux, et sa haine de l'ennemi était devenue la seule chose pour laquelle il semblait vivre.

Enfin, ils trouvèrent la lame dans une caverne gelée, scellée dans la glace et gardée. Muradin lut l'avertissement qui y était gravé et supplia Arthas de la laisser. Le prince refusa. Quand Arthas libéra l'épée, la glace vola en éclats, et un fragment frappa Muradin. Arthas prit Deuillegivre et continua sans lui.]=],
		},
		{
			title = "À Ironforge",
			text = [=[Les nains se souviennent de Muradin comme d'un héros de l'{link:alliance}Alliance{/link} et du frère de leur roi. Sa perte est un poids de plus que porte {link:magni-bronzebeard}Magni{/link}, à côté d'une armée loin de chez elle et d'une fille enlevée par les {link:dark-iron-dwarves}Sombrefer{/link}. Dans les salles d'{link:ironforge}Ironforge{/link}, son nom est prononcé avec tristesse, et avec la fierté obstinée que les nains réservent à ceux qui sont tombés en faisant ce qu'ils croyaient juste.]=],
		},
		{
			title = "Non consigné",
			text = [=[Ce qu'il advint de Muradin après ce jour n'est pas connu à {link:ironforge}Ironforge{/link}. Son peuple croit qu'il mourut dans la glace. Aucune chronique connue des nains ne dit le contraire.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son frère" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "son frère" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "son élève" },
	},
})

Translate("frFR", "brann-bronzebeard", {
	title = "Brann Bronzebeard",
	subtitle = "Explorateur de la Ligue des explorateurs",
	found = "En voyage, loin d'Ironforge",
	allegiance = "Royaume d'Ironforge · Ligue des explorateurs",
	aliases = { "Brann" },
	sections = {
		{
			title = "Résumé",
			text = [=[Brann Bronzebeard est le plus jeune frère du {link:magni-bronzebeard}roi Magni{/link}. Là où Magni prit la couronne et {link:muradin-bronzebeard}Muradin{/link} le marteau, Brann prit la carte et la lanterne. C'est l'explorateur le plus célèbre de la {link:explorers-league}Ligue des explorateurs{/link}, un {link:dwarves}nain{/link} qui préfère dormir dans une ruine des titans que dans un lit royal.]=],
		},
		{
			title = "Importance",
			text = [=[Brann est l'esprit vivant de la grande question de la Ligue : d'où viennent les nains ? Il a passé sa vie à fouiller les lieux anciens du monde pour trouver la réponse, et son nom ouvre des portes qui restaient closes aux fouilleurs de moindre renom. Les érudits de la Ligue, au {link:hall-of-explorers}Hall of Explorers{/link}, poursuivent son travail pendant qu'il voyage.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il a exploré des ruines à travers les {link:eastern-kingdoms}Royaumes de l'est{/link} et au-delà, en quête des origines des nains.
• Il compte parmi les membres éminents de la {link:explorers-league}Ligue des explorateurs{/link}.]=],
		},
		{
			title = "La grande question",
			text = [=[La question qui anime Brann est celle que se pose toute la Ligue : les nains furent-ils vraiment façonnés dans la pierre par les titans ? En son absence, ses collègues se sont approchés d'une réponse plus que jamais auparavant. Des profondeurs d'{link:uldaman}Uldaman{/link}, ils ont rapporté des archives des œuvres des titans, et ces archives désignent des caveaux plus grands encore dans les déserts du sud. C'est le genre de découverte à laquelle Brann a consacré sa vie.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les voyages de Brann l'ont mené loin d'{link:ironforge}Ironforge{/link}, et personne dans la cité ne peut dire où il se trouve aujourd'hui. De ses périples, les salles du {link:high-seat}High Seat{/link} n'entendent que des rumeurs. Cette entrée ne consigne que ce qui est certain.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son frère aîné" },
		{ id = "muradin-bronzebeard", name = "Muradin Bronzebeard", note = "son frère" },
		{ id = "high-explorer-magellas", name = "Grand explorateur Magellas", note = "dirige la Ligue en son absence" },
	},
})

Translate("frFR", "gelbin-mekkatorque", {
	title = "Gelbin Mekkatorque",
	subtitle = "Grand artisan, roi des gnomes",
	found = "Tinker Town, Ironforge",
	hint = "Cherchez le grand artisan à Tinker Town.",
	allegiance = "Exilés de Gnomeregan · Alliance",
	aliases = { "Mekkatorque", "grand artisan Mekkatorque", "Gelbin", "grand artisan Gelbin Mekkatorque" },
	sections = {
		{
			title = "Résumé",
			text = [=[Gelbin Mekkatorque est le grand artisan des gnomes, le roi d'un peuple qui a perdu son royaume. Il régnait sur {link:gnomeregan}Gnomeregan{/link} quand la cité était grande. Il règne désormais depuis un atelier de {link:tinker-town}Tinker Town{/link}, hôte des nains, alors que la plupart de son peuple est mort, empoisonné ou dispersé. Il n'a perdu ni son esprit ni sa volonté. Il entend rentrer chez lui.]=],
		},
		{
			title = "Importance",
			text = [=[Mekkatorque maintient l'unité des gnomes. Sans lui, les exilés ne seraient qu'une foule de réfugiés. Avec lui, ils restent une nation, avec un siège parmi les peuples de l'{link:alliance}Alliance{/link} et une revendication sur leur cité à laquelle ils n'ont jamais renoncé.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirigea les gnomes de {link:gnomeregan}Gnomeregan{/link} en tant que grand artisan.
• Quand les troggs se soulevèrent sous la cité, il retourna contre eux les propres arts des gnomes dans une purge désespérée, et la cité fut empoisonnée.
• Il mena les survivants jusqu'à {link:ironforge}Ironforge{/link} et fit de {link:tinker-town}Tinker Town{/link} leur foyer.
• Il renvoie des volontaires à Gnomeregan pour récupérer ce qui fut laissé derrière, et pour frapper le traître qui la tient.]=],
		},
		{
			title = "La chute de la cité",
			text = [=[Aucune chronique ne dit en quelle année les troggs remontèrent des profondeurs sous {link:gnomeregan}Gnomeregan{/link}. Ils vinrent en grand nombre, et la cité ne put les repousser. Mekkatorque choisit de les purger avec une arme de la fabrication des gnomes. Elle tua des troggs, mais elle tua aussi un très grand nombre de gnomes, et elle laissa la cité imprégnée de poison. Beaucoup de ceux qui survécurent furent changés en lépreux malades et privés de raison. Les autres s'enfuirent dans les neiges de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
		{
			title = "La cour en exil",
			text = [=[À {link:tinker-town}Tinker Town{/link}, le peuple du grand artisan n'a pas cessé de travailler. Le maître bricoleur Overspark espère réparer son pauvre Techbot, dont l'esprit fut inversé lors de la chute. Le maître mécanicien Castpipe organise des groupes pour récupérer des archives vitales dans les terminaux de la cité. Klockmort Spannerspan a besoin des pièces que personne n'a pensé à emporter dans la fuite. Chacune de ces missions est un petit pas de retour vers {link:gnomeregan}Gnomeregan{/link}, et Mekkatorque les encourage toutes.]=],
		},
	},
	chapters = {
		{
			title = "La grande trahison",
			hint = "Abattez le traître qui règne sur Gnomeregan.",
			text = [=[Mekkatorque avait fait confiance à {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}. Il n'avait jamais imaginé que Thermaplugg le trahirait, lui et tout le peuple {link:gnomes}gnome{/link}, et il ne comprend toujours pas pourquoi, car le pouvoir et la richesse seraient venus à Thermaplugg avec le temps. À présent, le traître siège dans les ruines, roi de rien du tout. Quand la nouvelle arriva que Thermaplugg était tombé, Mekkatorque s'autorisa une plaisanterie amère, puis tourna ses pensées vers le jour où les gnomes reprendraient leur cité.]=],
		},
	},
	mentions = {
		{ text = "Sauvetage de données" },
		{ text = "Sauvez le cerveau de Techbot !" },
		{ text = "Artificiels essentiels" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Mekgénieur Thermaplugg", note = "le traître" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son hôte et allié" },
		{ id = "razzle-sprysprocket", name = "Razzle Sprysprocket", note = "l'un des siens, en quête d'un remède" },
	},
})

Translate("frFR", "royal-historian-archesonus", {
	title = "Historienne royale Archesonus",
	subtitle = "Historienne royale d'Ironforge",
	found = "Le High Seat, à côté du trône",
	hint = [=[Parlez à l'historienne qui garde la mémoire du royaume à côté du trône.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Archesonus" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'historienne royale Archesonus garde la mémoire d'{link:ironforge}Ironforge{/link} à côté du trône du {link:magni-bronzebeard}roi Magni{/link}. Quiconque le demande peut entendre d'elle l'histoire du royaume. Le récit qu'elle raconte avec le plus de gravité est celui des {link:dark-iron-dwarves}Sombrefer{/link}, et de la cité de {link:ruins-of-thaurissan}Thaurissan{/link}, qui brûla.]=],
		},
		{
			title = "Importance",
			text = [=[Archesonus est la voix du passé d'{link:ironforge}Ironforge{/link}. Les nains sont un peuple à la longue mémoire, et au {link:high-seat}High Seat{/link}, cette mémoire a une gardienne. Sa connaissance des {link:dark-iron-dwarves}Sombrefer{/link} est devenue urgente, car le vieil ennemi du royaume est de nouveau en marche.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle enseigne l'histoire d'{link:ironforge}Ironforge{/link} à ceux qui viennent au {link:high-seat}High Seat{/link}.
• Elle envoie des chercheurs aux {link:ruins-of-thaurissan}Ruines de Thaurissan{/link}, dans {link:burning-steppes}les Steppes{/link} ardentes, pour lire les reliques qui y sont restées.]=],
		},
	},
	chapters = {
		{
			title = "L'histoire de Thaurissan",
			hint = "Demandez à l'historienne royale l'histoire des Sombrefer.",
			text = [=[Archesonus commence loin en arrière, à l'époque où les {link:dark-iron-dwarves}Sombrefer{/link} avaient une cité à eux. {link:ruins-of-thaurissan}Thaurissan{/link} se dressait dans un pays verdoyant qui est aujourd'hui {link:burning-steppes}les Steppes{/link} ardentes, et en ce temps-là, les clans nains étaient en guerre les uns contre les autres. Puis une terrible explosion la détruisit, et la terre fut réduite en cendres sur des lieues à la ronde. Ce qui causa l'explosion, admet-elle, aucun historien ne peut le dire. Les Sombrefer qui survécurent entrèrent dans la montagne et recommencèrent. Des cendres s'éleva le Pic {link:blackrock-mountain}Blackrock{/link}, et {link:the-cauldron}le Chaudron{/link} de {link:searing-gorge}la Gorge des Vents brûlants{/link} fut fortifié. Bientôt, on murmura qu'un mal ancien gouvernait le royaume sombrefer de l'intérieur. Son récit s'achève dans le présent. On voit les Sombrefer plus souvent à la surface chaque année. Ils ont élevé des forts dans les {link:badlands}Terres ingrates{/link}, envoyé de grands groupes à {link:uldaman}Uldaman{/link} et ont même attaqué le barrage du {link:loch-modan}Loch Modan{/link}.]=],
		},
		{
			title = "Les ruines fumantes",
			hint = [=[Lisez les reliques de Thaurissan et rapportez-en les souvenirs.]=],
			text = [=[Les reliques de la cité en ruine renferment des souvenirs, et ceux qui les touchent les gardent. Une créature de pure flamme. Huit nains sombrefer lors d'un rituel. L'un d'eux, seul à la fin, agenouillé parmi sept morts devant un pilier de feu. Archesonus entendit ces souvenirs et dit qu'ils expliquaient bien des choses, et qu'il restait encore beaucoup à apprendre.]=],
		},
	},
	mentions = {
		{
			text = [=[Les ruines fumantes de {link:ruins-of-thaurissan}Thaurissan{/link}]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son roi" },
	},
})

Translate("frFR", "high-explorer-magellas", {
	title = "Grand explorateur Magellas",
	subtitle = "Grand explorateur de la Ligue des explorateurs",
	found = "Le Hall of Explorers",
	hint = "Parlez au grand explorateur dans le Hall of Explorers.",
	allegiance = "Ligue des explorateurs",
	aliases = { "Magellas" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le grand explorateur Magellas dirige la {link:explorers-league}Ligue des explorateurs{/link} depuis le {link:hall-of-explorers}Hall of Explorers{/link}. C'est un {link:dwarves}nain{/link} occupé, et il le fait savoir aux visiteurs. Pourtant, personne à {link:ironforge}Ironforge{/link} ne s'enthousiasme davantage pour une vraie découverte, et quand l'une d'elles arrive sur sa table, sa dignité s'envole par la fenêtre.]=],
		},
		{
			title = "Importance",
			text = [=[Sous Magellas, la Ligue poursuit la question qui compte le plus pour elle : la preuve que les nains furent façonnés dans la pierre par les titans, que les anciennes archives appellent les Créateurs. Il croit que cette preuve est peut-être à portée de main.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige les expéditions de la Ligue et récompense ceux qui la servent en puisant dans le trésor de la Ligue.
• Il étudie les disques de Norgannon miniatures rapportés d'{link:uldaman}Uldaman{/link}.
• Il tourne les regards de la Ligue vers {link:valley-of-the-watchers}Uldum{/link}, loin au sud, en {link:tanaris}Tanaris{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les disques de platine",
			hint = [=[Rapportez à la Ligue une trouvaille des profondeurs d'Uldaman.]=],
			text = [=[Quand une copie en miniature des disques de Norgannon fut posée devant lui, Magellas demanda où elle avait été trouvée, puis le demanda encore, et ne put croire les réponses. Il la qualifia de trouvaille du siècle. Si les disques disaient ce qu'il pensait, ils trancheraient une fois pour toutes la vieille question de l'origine des nains.]=],
		},
		{
			title = "L'appel d'Uldum",
			hint = [=[Suivez les disques jusqu'aux portes d'Uldum et faites votre rapport.]=],
			text = [=[Les disques menaient aux portes scellées d'{link:valley-of-the-watchers}Uldum{/link}, où un autre gardien de pierre parla de plaques manquantes. Magellas convint avec ses érudits que la recherche devait attendre qu'ils sachent où regarder. Il promit que, le moment venu, la Ligue renverrait les mêmes mains sur le terrain.]=],
		},
	},
	mentions = {
		{ text = "Les disques de platine" },
		{ text = "Présages d'{link:valley-of-the-watchers}Uldum{/link}" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historien Karnik", note = "son érudit" },
		{ id = "brann-bronzebeard", name = "Brann Bronzebeard", note = "l'explorateur le plus célèbre de la Ligue" },
	},
})

Translate("frFR", "advisor-belgrum", {
	title = "Conseiller Belgrum",
	subtitle = "Conseiller du roi",
	found = "Le Hall of Explorers",
	hint = [=[Trouvez le conseiller du roi parmi les érudits du Hall of Explorers.]=],
	allegiance = "Royaume d'Ironforge · Ligue des explorateurs",
	aliases = { "Belgrum" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le conseiller Belgrum parle avec l'autorité du roi au {link:hall-of-explorers}Hall of Explorers{/link}. Quand la nouvelle arriva que le clan Shadowforge des {link:dark-iron-dwarves}Sombrefer{/link} avait assassiné l'explorateur Hammertoe dans les {link:badlands}Terres ingrates{/link}, c'est Belgrum qui ordonna l'attaque contre leur forteresse, et Belgrum qui jura que la quête de Hammertoe pour la Tablette de volonté des titans serait menée à son terme.]=],
		},
		{
			title = "Importance",
			text = [=[Belgrum est le pont entre le savoir de la Ligue et le pouvoir du roi. Quand les découvertes de la Ligue deviennent des affaires de guerre, c'est par lui que la couronne agit.]=],
		},
	},
	mentions = {
		{ text = "Transmettre l'avertissement d'une menace" },
		{ text = "Un ambassadeur du mal" },
		{ text = "Les tablettes de volonté perdues" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Historien Karnik", note = "lui apporte des nouvelles" },
	},
})

Translate("frFR", "historian-karnik", {
	title = "Historien Karnik",
	subtitle = "Historien de la Ligue des explorateurs",
	found = "Le Hall of Explorers",
	hint = [=[Trouvez l'historien de la Ligue qui pleure son ami Hammertoe.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Karnik" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'historien Karnik travailla avec l'explorateur Hammertoe pour retrouver les artefacts perdus d'{link:uldaman}Uldaman{/link}, jusqu'à ce que les Shadowforge tuent Hammertoe pour ce qu'il savait. Karnik parle encore avec l'esprit de son ami. Il étudie aussi les lieux anciens du sud, et il a trouvé des indices sur {link:stranglethorn-vale}la Vallée{/link} des guetteurs, dans {link:tanaris}le désert de Tanaris{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Karnik est la mémoire de la Ligue quant au prix qu'a coûté {link:uldaman}Uldaman{/link}. Par lui, la mort de Hammertoe devint une cause pour tout le royaume.]=],
		},
	},
	mentions = {
		{ text = "Perspective de foi" },
		{ text = "Transmettre l'avertissement d'une menace" },
		{ text = "Voir ce qui se passe" },
		{ text = "Retour à {link:ironforge}Ironforge{/link}" },
	},
	bonds = {
		{ id = "advisor-belgrum", name = "Conseiller Belgrum", note = "parle au nom du roi" },
		{ id = "high-explorer-magellas", name = "Grand explorateur Magellas", note = "son supérieur" },
	},
})

Translate("frFR", "prospector-stormpike", {
	title = "Prospecteur Stormpike",
	subtitle = "Prospecteur de la Ligue des explorateurs",
	found = "Le Hall of Explorers",
	hint = "Trouvez le prospecteur colérique du Hall of Explorers.",
	allegiance = "Ligue des explorateurs",
	sections = {
		{
			title = "Résumé",
			text = [=[Le prospecteur {link:stormpike-guard}Stormpike{/link} supervise les fouilles de la Ligue depuis le {link:hall-of-explorers}Hall of Explorers{/link}, et il ne supporte guère les affaires futiles. Il s'emporte vite quand une fouille avance lentement, et plus vite encore quand de la poudre explosive disparaît. Sous ce tempérament se cache la loyauté : quand les troggs envahirent {link:uldaman}Uldaman{/link}, sa première pensée alla à son ami {link:the-lost-dwarves}Baelog{/link} et aux nains pris au piège derrière les lignes.]=],
		},
		{
			title = "Importance",
			text = [=[{link:stormpike-guard}Stormpike{/link} veille à ce que les fouilleurs de la Ligue soient approvisionnés et que ses expéditions avancent, de l'excavation d'{link:prospector-ironband}Ironband{/link} au {link:loch-modan}Loch Modan{/link} jusqu'aux profondeurs d'{link:uldaman}Uldaman{/link}.]=],
		},
	},
	mentions = {
		{ text = "Au rapport à {link:ironforge}Ironforge{/link}" },
		{ text = "De la poudre pour {link:prospector-ironband}Ironband{/link}" },
		{ text = "{link:the-lost-dwarves}Les nains perdus{/link}" },
	},
	bonds = {
		{ id = "high-explorer-magellas", name = "Grand explorateur Magellas", note = "dirige la Ligue" },
	},
})

Translate("frFR", "senator-barin-redstone", {
	title = "Sénateur Barin Redstone",
	subtitle = "Sénateur d'Ironforge",
	found = "Le High Seat",
	hint = "Trouvez le sénateur acariâtre à la cour du roi.",
	allegiance = "Sénat d'Ironforge",
	aliases = { "Barin Redstone" },
	sections = {
		{
			title = "Résumé",
			text = [=[Barin Redstone siège au Sénat d'{link:ironforge}Ironforge{/link} et assiste à la cour du roi au {link:high-seat}High Seat{/link}. Il est connu pour son caractère acariâtre. Quand arriva de {link:kharanos}Kharanos{/link} un rapport qui invoquait l'autorité même du roi pour des travaux sur le terrain, Redstone fut outré, contre l'auteur comme contre le roi, et il prévint que le Sénat ne serait pas content.]=],
		},
		{
			title = "Importance",
			text = [=[Redstone montre qu'{link:ironforge}Ironforge{/link} n'est pas gouvernée par le roi seul. Le Sénat garde jalousement ses pouvoirs.]=],
		},
	},
	mentions = {
		{ text = "Les rapports" },
	},
	bonds = {
		{ id = "senir-whitebeard", name = "Senir Whitebeard", note = "a écrit le rapport" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "son roi" },
	},
})

Translate("frFR", "afadra-dunwall", {
	title = "Afadra Dunwall",
	subtitle = "Gardienne du savoir d'Ironforge",
	found = "Old Ironforge, sous le High Seat",
	hint = [=[Cherchez la gardienne du savoir qui veille sur la descente vers le Hall of Thanes.]=],
	allegiance = "Royaume d'Ironforge",
	aliases = { "Afadra" },
	sections = {
		{
			title = "Résumé",
			text = [=[Afadra Dunwall est une gardienne du savoir d'{link:ironforge}Ironforge{/link}, l'une des gardiennes qui veillent sur les tombeaux du {link:hall-of-thanes}Hall of Thanes{/link}. D'étranges bruits sont venus des caveaux en contrebas, et les esprits des morts, qui ont le sommeil léger, se sont réveillés. Afadra veut qu'ils retrouvent le repos. Elle veut aussi que les autres gardiens cessent de refuser leurs devoirs à cause des fantômes.]=],
		},
		{
			title = "Importance",
			text = [=[Afadra est l'une des rares personnes qui gardent encore les plus anciens morts d'{link:ironforge}Ironforge{/link}. Son devoir est devenu dangereux.]=],
		},
	},
	mentions = {
		{ text = "Les morts sans repos" },
	},
	bonds = {
		{ id = "thom-filch", name = "Thom Filch", note = "un autre veilleur des caveaux" },
	},
})

Translate("frFR", "thom-filch", {
	title = "Thom Filch",
	subtitle = "Le gnome des caveaux",
	found = "Old Ironforge, sous le High Seat",
	hint = [=[Trouvez le gnome d'Old Ironforge qui patrouillait là où il n'aurait pas dû être.]=],
	allegiance = "Inconnue",
	sections = {
		{
			title = "Résumé",
			text = [=[Thom Filch est un {link:gnomes}gnome{/link} qui, selon ses propres mots, patrouillait dans les caveaux sous {link:ironforge}Ironforge{/link} quand les {link:dark-iron-dwarves}Sombrefer{/link} jaillirent de la roche à bord de machines fouisseuses. Il veut que les reliques inestimables des caveaux soient récupérées. Il les appelle butin, puis patrimoine culturel, et promet que chacune sera cataloguée et remise à sa place. Peu de ceux qui l'entendent le croient.]=],
		},
		{
			title = "Importance",
			text = [=[Thom Filch fut le premier à voir les {link:dark-iron-dwarves}Sombrefer{/link} surgir dans les caveaux, quoi qu'il ait été en train d'y faire à ce moment-là.]=],
		},
	},
	mentions = {
		{ text = "Des héritages importants" },
	},
	bonds = {
		{ id = "afadra-dunwall", name = "Afadra Dunwall", note = "garde les tombeaux où il rôde" },
	},
})
